def generate_synthetic_passport(rng: random.Random) -> str:
    letter = rng.choice("ABCDEFGHJKLMNPQRSTUVWXYZ")
    digits = "".join(str(rng.randint(0, 9)) for _ in range(7))
    return f"{letter}{digits}"

def generate_synthetic_aadhaar(rng: random.Random, valid_checksum: bool = True) -> str:
    first_11 = "".join(str(rng.randint(1 if i == 0 else 0, 9)) for i in range(11))
    if valid_checksum:
        check_digit = compute_verhoeff_check_digit(first_11)
        return f"{first_11}{check_digit}"
    else:
        # Invalid checksum
        check_digit = int(compute_verhoeff_check_digit(first_11))
        bad_digit = (check_digit + rng.randint(1, 9)) % 10
        return f"{first_11}{bad_digit}"

def generate_synthetic_dl(rng: random.Random) -> str:
    st = rng.choice(STATE_CODES)
    rto = f"{rng.randint(1, 20):02d}"
    year = rng.randint(2010, 2024)
    seq = f"{rng.randint(1, 9999999):07d}"
    return f"{st}-{rto}{year}{seq}"

def generate_synthetic_embedding(rng: random.Random, dim: int = 512) -> np.ndarray:
    vec = np.array([rng.gauss(0, 1) for _ in range(dim)], dtype=np.float32)
    norm = np.linalg.norm(vec)
    if norm > 0:
        vec /= norm
    return vec

def generate_dataset(
    count: int = 1000,
    blacklisted_pct: float = 0.20,
    expired_pct: float = 0.15,
    valid_pct: float = 0.60,
    duplicate_pairs: int = 25,
    num_checkpoints: int = 10,
    num_officers: int = 50,
    seed: int = 42
):
    print(f"Generating DEMO-LARGE dataset: count={count}, checkpoints={num_checkpoints}, officers={num_officers}, seed={seed}...")
    rng = random.Random(seed)

    db = SessionLocal()
    try:
        # 1. Scale Checkpoints
        existing_cp_codes = {cp.checkpoint_code: cp for cp in db.query(Checkpoint).all()}
        new_cps = []
        for i in range(num_checkpoints):
            code = f"CP-SECTOR-{i+1:02d}"
            loc_tuple = CHECKPOINT_LOCATIONS[i % len(CHECKPOINT_LOCATIONS)]
            if code not in existing_cp_codes:
                cp = Checkpoint(
                    checkpoint_code=code,
                    name=f"{loc_tuple[0]} (Sec-{i+1:02d})",
                    location=loc_tuple[1],
                    state=loc_tuple[2],
                    district=loc_tuple[3],
                    status="ACTIVE"
                )
                new_cps.append(cp)
        
        if new_cps:
            db.add_all(new_cps)
            db.commit()
            print(f"  + Added {len(new_cps)} synthetic Checkpoints")

        all_cps = db.query(Checkpoint).all()
        cp_ids = [c.id for c in all_cps]

        # 2. Scale Officers
        existing_badges = {o.badge_id: o for o in db.query(Officer).all()}
        new_officers = []
        roles = ["OFFICER", "SUPERVISOR", "ANALYST", "ADMIN"]
        role_weights = [0.70, 0.15, 0.10, 0.05]

        for i in range(num_officers):
            badge = f"SSB-{8000 + i}"
            if badge not in existing_badges:
                assigned_cp = rng.choice(all_cps) if all_cps else None
                role = rng.choices(roles, weights=role_weights)[0]
                name = f"{rng.choice(FIRST_NAMES)} {rng.choice(LAST_NAMES)}"
                off = Officer(
                    badge_id=badge,
                    full_name=f"{'Insp.' if role == 'OFFICER' else 'AC'} {name}",
                    role=role,
                    checkpoint_id=assigned_cp.id if assigned_cp else None,
                    checkpoint_location=assigned_cp.name if assigned_cp else "Raxaul Checkpoint",
                    password_hash=get_password_hash("BorderSecurity2026!"),
                    status="ACTIVE"
                )
                new_officers.append(off)

        if new_officers:
            db.add_all(new_officers)
            db.commit()
            print(f"  + Added {len(new_officers)} synthetic Security Officers")

        # 3. Generate Reference Documents
        existing_ref_docs = {r.document_number for r in db.query(ReferenceDocument).all()}
        existing_black_docs = {b.document_number for b in db.query(BlacklistedDocument).all()}
        
        doc_types = ["PASSPORT", "AADHAAR", "DRIVING_LICENCE"]
        ref_records = []
        black_records = []
        biometric_records = []

        total_blacklist = int(count * blacklisted_pct)
        total_expired = int(count * expired_pct)
        total_valid = count - total_blacklist - total_expired

        # Lookout Circulars / Blacklisted
        for i in range(total_blacklist):
            dtype = rng.choice(doc_types)
            name = f"{rng.choice(FIRST_NAMES)} {rng.choice(LAST_NAMES)}".upper()
            dob = f"{rng.randint(1965, 2004)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"
            issue = f"{rng.randint(2015, 2022)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"
            expiry = f"{rng.randint(2027, 2035)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"

            if dtype == "PASSPORT":
                num = generate_synthetic_passport(rng)
            elif dtype == "AADHAAR":
                num = generate_synthetic_aadhaar(rng, valid_checksum=True)
            else:
                num = generate_synthetic_dl(rng)

            clean_num = num.replace("-", "").replace(" ", "")
            if clean_num in existing_ref_docs or clean_num in existing_black_docs:
                continue

            existing_ref_docs.add(clean_num)
            existing_black_docs.add(clean_num)

            reason = rng.choice(REASONS_BLACKLIST)
            status = "BLACKLISTED" if i % 4 != 0 else "SUSPICIOUS"
            source = "MHA_LOOKOUT" if i % 2 == 0 else "INTERPOL_SLTD"

            ref_records.append(
                ReferenceDocument(
                    document_type=dtype,
                    document_number=clean_num,
                    holder_name=name,
                    date_of_birth=dob,
                    issue_date=issue,
                    expiry_date=expiry,
                    status=status,
                    reason=reason,
                    source_type=source
                )
            )

            if status == "BLACKLISTED":
                black_records.append(
                    BlacklistedDocument(
                        document_type=dtype,
                        document_number=clean_num,
                        holder_name=name,
                        reason=reason
                    )
                )

        # Expired Records
        for _ in range(total_expired):
            dtype = rng.choice(doc_types)
            name = f"{rng.choice(FIRST_NAMES)} {rng.choice(LAST_NAMES)}".upper()
            dob = f"{rng.randint(1960, 1995)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"
            issue = f"{rng.randint(2005, 2013)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"
            expiry = f"{rng.randint(2018, 2023)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"

            if dtype == "PASSPORT":
                num = generate_synthetic_passport(rng)
            elif dtype == "AADHAAR":
                num = generate_synthetic_aadhaar(rng, valid_checksum=True)
            else:
                num = generate_synthetic_dl(rng)

            clean_num = num.replace("-", "").replace(" ", "")
            if clean_num in existing_ref_docs:
                continue
            existing_ref_docs.add(clean_num)

            ref_records.append(
                ReferenceDocument(
                    document_type=dtype,
                    document_number=clean_num,
                    holder_name=name,
                    date_of_birth=dob,
                    issue_date=issue,
                    expiry_date=expiry,
                    status="EXPIRED",
                    reason="EXPIRED_DOCUMENT: Travel credential exceeded maximum statutory validity period.",
                    source_type="SYNTHETIC_EXPIRED_SET"
                )
            )

        # Valid Benchmark Records
        for _ in range(total_valid):
            dtype = rng.choice(doc_types)
            name = f"{rng.choice(FIRST_NAMES)} {rng.choice(LAST_NAMES)}".upper()
            dob = f"{rng.randint(1970, 2005)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"
            issue = f"{rng.randint(2020, 2024)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"
            expiry = f"{rng.randint(2028, 2035)}-{rng.randint(1, 12):02d}-{rng.randint(1, 28):02d}"

            if dtype == "PASSPORT":
                num = generate_synthetic_passport(rng)
            elif dtype == "AADHAAR":
                num = generate_synthetic_aadhaar(rng, valid_checksum=True)
            else:
                num = generate_synthetic_dl(rng)

            clean_num = num.replace("-", "").replace(" ", "")
            if clean_num in existing_ref_docs:
                continue
            existing_ref_docs.add(clean_num)

            ref_records.append(
                ReferenceDocument(
                    document_type=dtype,
                    document_number=clean_num,
                    holder_name=name,
                    date_of_birth=dob,
                    issue_date=issue,
                    expiry_date=expiry,
                    status="VALID",
                    reason="VERIFIED_BENCHMARK: Valid traveler identity enrolled in reference benchmark.",
                    source_type="SYNTHETIC_VALID_SET"
                )
            )

            # Enroll biometric
            emb = generate_synthetic_embedding(rng)
            biometric_records.append(
                TravelerBiometric(
                    document_number=clean_num,
                    holder_name=name,
                    face_embedding=emb.tobytes(),
                    embedding_engine="OpenCV-SpatialGradient-512D",
                    embedding_dimension=512,
                    status="ACTIVE"
                )
            )

        # 4. Duplicate Impostor Collisions
        for pair_idx in range(duplicate_pairs):
            primary_emb = generate_synthetic_embedding(rng)
            name_a = f"{rng.choice(FIRST_NAMES)} {rng.choice(LAST_NAMES)}".upper()
            name_b = f"{rng.choice(FIRST_NAMES)} {rng.choice(LAST_NAMES)}".upper()

            doc_a = generate_synthetic_passport(rng)
            doc_b = generate_synthetic_aadhaar(rng, valid_checksum=True)

            biometric_records.append(
                TravelerBiometric(
                    document_number=doc_a,
                    holder_name=name_a,
                    face_embedding=primary_emb.tobytes(),
                    embedding_engine="OpenCV-SpatialGradient-512D",
                    embedding_dimension=512,
                    status="ACTIVE"
                )
            )

            noise = np.array([rng.gauss(0, 0.05) for _ in range(512)], dtype=np.float32)
            collision_emb = primary_emb + noise
            collision_emb /= np.linalg.norm(collision_emb)

            biometric_records.append(
                TravelerBiometric(
                    document_number=doc_b,
                    holder_name=name_b,
                    face_embedding=collision_emb.tobytes(),
                    embedding_engine="OpenCV-SpatialGradient-512D",
                    embedding_dimension=512,
                    status="ACTIVE"
                )
            )

        db.add_all(ref_records)
        db.add_all(black_records)
        db.add_all(biometric_records)
        db.commit()

        print(f"Successfully generated DEMO-LARGE dataset:")
        print(f"  - Checkpoints in DB: {db.query(Checkpoint).count()}")
        print(f"  - Officers in DB: {db.query(Officer).count()}")
        print(f"  - Reference Documents in DB: {db.query(ReferenceDocument).count()}")
        print(f"  - Lookout Circulars in DB: {db.query(BlacklistedDocument).count()}")
        print(f"  - Biometric Vectors in DB: {db.query(TravelerBiometric).count()}")

    finally:
        db.close()

def main():
    parser = argparse.ArgumentParser(description="Generate scalable synthetic reference datasets for SSB document screening.")
    parser.add_argument("--count", type=int, default=1000, help="Total number of reference identity records to generate.")
    parser.add_argument("--checkpoints", type=int, default=10, help="Total number of border checkpoints to seed.")
    parser.add_argument("--officers", type=int, default=50, help="Total number of personnel accounts to seed.")
    parser.add_argument("--blacklisted", type=float, default=0.20, help="Fraction of records to flag as blacklisted / lookout circular.")
    parser.add_argument("--expired", type=float, default=0.15, help="Fraction of records to flag as expired.")
    parser.add_argument("--valid", type=float, default=0.65, help="Fraction of records to flag as valid benchmark identities.")
    parser.add_argument("--duplicate-biometric", type=int, default=25, help="Number of biometric duplicate collision pairs to generate.")
    parser.add_argument("--seed", type=int, default=42, help="Deterministic random seed.")
    args = parser.parse_args()

    generate_dataset(
        count=args.count,
        num_checkpoints=args.checkpoints,
        num_officers=args.officers,
        blacklisted_pct=args.blacklisted,
        expired_pct=args.expired,
        valid_pct=args.valid,
        duplicate_pairs=args.duplicate_biometric,
        seed=args.seed
    )

if __name__ == "__main__":
    main()
